old_qing = """    figures:[
      {name:'康熙',desc:'爱新觉罗·玄烨（1654—1722年），清朝第四位皇帝。八岁登基智擒鳌拜亲政，平三藩收台湾、三征噶尔丹、抗击沙俄侵略签订《尼布楚条约》。在位六十一年开创康乾盛世的局面，是中国历史上在位时间最长的皇帝。'},
      {name:'雍正',desc:'爱新觉罗·胤禛（1678—1735年），清朝第五位皇帝。整顿吏治设立军机处加强皇权、推行摊丁入亩耗羡归公等财政改革，勤政异常据说每天批阅奏折万余字，为乾隆盛世的繁荣奠定了坚实基础。'},
      {name:'乾隆',desc:'爱新觉罗·弘历（1711—1799年），清朝第六位皇帝。在位六十年（退位后以太上皇训政三年），康乾盛世在他治下达到顶峰，疆域超一千三百万平方公里人口突破三亿。编纂《四库全书》。晚年宠信和珅吏治腐败，盛世之下危机暗伏。'},
      {name:'林则徐',desc:'字元抚（1785—1850年），清代政治家民族英雄。任湖广总督期间严禁鸦片，1839年奉旨赴广州在虎门海滩当众销毁鸦片二百三十七万斤。鸦片战争爆发后被革职流放新疆伊犁，在流放途中写下"苟利国家生死以，岂因祸福避趋之"。'},
      {name:'曾国藩',desc:'字伯涵（1811—1872年），晚清名臣湘军创始人。组建湘军平定太平天国运动，与李鸿章左宗棠张之洞并称"晚清四大名臣"。倡导洋务运动创办江南制造总局，其家书家训影响深远，被誉为"立德立功立言三不朽"的典范。'},
      {name:'李鸿章',desc:'字渐甫（1823—1901年），晚清重臣。创建淮军、倡导洋务运动创办轮船招商局等企业、筹建北洋水师。先后代表清政府签订《马关条约》《辛丑条约》等不平等条约，背负了深重的历史争议。临终前留下"三百年来伤国步，八千里外吊民残"的哀叹。'},
      {name:'左宗棠',desc:'字季高（1812—1885年），晚清名臣。年届六十九岁抬棺出征率领湘军收复被阿古柏侵占十二年的新疆全境，迫使沙俄归还伊犁。如果没有左宗棠的收复行动，今天中国的版图上可能就没有占国土面积六分之一的新疆。'},
      {name:'慈禧太后',desc:'（1835—1908年），清朝咸丰帝妃，同治光绪两朝的实际统治者。统治中国四十七年，发动辛酉政变夺取最高权力，镇压戊戌变法囚禁光绪帝。在位期间中国屡遭列强侵略割地赔款，是中国近代屈辱史中最具争议的人物。'},
      {name:'孙中山',desc:'名文字德明号逸仙（1866—1925年），中国近代民族民主主义革命的先行者。创建兴中会同盟会，提出三民主义，领导辛亥革命推翻延续两千余年的封建帝制。1912年就任中华民国临时大总统，被尊为"国父"。'},
      {name:'康有为',desc:'字广厦号长素（1858—1927年），晚清维新派领袖。公车上书反对签订《马关条约》，主导戊戌变法推动制度革新，变法失败后流亡海外十六年。著有《大同书》构想理想社会，是中国近代重要的思想家和改革家。'}
    ],
    inventions:['《四库全书》','《红楼梦》','京剧','圆明园','《康熙字典》'],"""

new_qing = """    figures:[
      {name:'康熙',
        basicInfo:'爱新觉罗·玄烨（1654—1722年），清朝第四位皇帝清圣祖，顺治帝第三子。八岁登基十四岁智擒权臣鳌拜亲政。在位六十一年——平三藩、收台湾、三征噶尔丹、抗击沙俄签订《尼布楚条约》、平定西藏。开创了康乾盛世的局面，是中国历史上在位时间最长的皇帝。庙号"圣祖"意为圣德之祖。',
        lifeStory:'康熙八岁丧父（顺治帝据说出家五台山）十岁丧母在祖母孝庄太后的辅佐下成长。1669年仅十六岁的康熙以摔跤游戏为掩护智擒权臣鳌拜——他训练了一批少年摔跤手趁鳌拜入宫不备将其擒拿。1673年力排众议下令撤藩引发吴三桂等"三藩之乱"——战火半年内燃遍半壁江山。年轻的康熙沉着应对以分化瓦解之计先打最强的吴三桂——1681年最终平定叛乱。1683年派施琅率水师攻取澎湖郑克塽投降台湾纳入清朝版图。三次亲征噶尔丹（1690-1697年）彻底摧毁了准噶尔汗国的威胁。1689年与沙俄签订《尼布楚条约》——中国历史上第一个与外国签订的平等边界条约。晚年因太子问题和九王夺嫡心力交瘁。',
        governance:'第一、平定三藩——以二十岁出头的年纪沉着应对半壁江山的大叛乱。第二、收台湾——在台湾设一府三县隶属福建省首次将台湾纳入中央行政体系。第三、三征噶尔丹——亲率大军远征蒙古草原消灭了准噶尔汗国对清朝北疆的威胁。第四、《尼布楚条约》——以外交谈判划定中俄东段边界展现了大国的理性。第五、治理黄河——六次南巡视察河工亲身研究和决策治水方案。',
        evaluation:'康熙帝是中国历史上最杰出的帝王之一。他的伟大在于"全面发展"——政治军事外交文化科技无一短板。但他晚年对太子问题的反复——两立两废太子——导致"九王夺嫡"的残酷内斗，给雍正留下了难以弥合的皇室裂痕。康熙时代的开放性——允许传教士进入宫中使用西方天文仪器——也在雍正朝之后逐渐封闭。',
        anecdotes:'智擒鳌拜——训练少年摔跤手趁鳌拜入宫将其擒拿十六岁的少年天子展示了过人的胆略和计谋。六下江南——以体察民情巡视河工为目的成为后世"微服私访"传说的原型。与西方传教士——康熙向汤若望南怀仁等传教士学习天文数学和地理知识是中国历代帝王中最具科学素养者。'},
      {name:'雍正',
        basicInfo:'爱新觉罗·胤禛（1678—1735年），清朝第五位皇帝清世宗，康熙帝第四子。在"九王夺嫡"中最终胜出四十五岁即位。在位十三年——整顿吏治设立军机处加强皇权、推行"摊丁入亩""耗羡归公""改土归流"等重大改革使清朝财政从入不敷出扭转为盈余数千万两。勤政异常——据说每天批阅奏折万余字、睡眠不足四个小时。为乾隆盛世的繁荣奠定了坚实的制度基础和财政基础。庙号"世宗"意为世代宗法。',
        lifeStory:'雍正的人生是一部逆袭史。在康熙晚年九位皇子争夺储位的残酷斗争中他不显山不露水不结党不营私——每天在府中念佛抄经给人"闲人"的印象。但康熙看中他办事"不徇情面"的作风——多次委派他处理棘手事务。1722年康熙驾崩隆科多宣诏传位于胤禛（"传位十四子"还是"传位于四子"的谜案至今众说纷纭）。即位后他以铁腕手段处理政敌——八弟允禩九弟允禟被圈禁致死。但他在治国上极其勤勉——昼夜批阅奏折"以一人治天下"——在位十三年批阅奏折超过两万件（现存）。他推行的"摊丁入亩"（将人头税摊入田亩由地多者多负担）是中国赋役制度史上的重大进步。1735年暴毙于圆明园享年五十八岁。',
        governance:'第一、整顿吏治——"耗羡归公"将各地官员私下收取的附加税转为正式收入杜绝了最普遍的贪腐渠道。第二、摊丁入亩——将人头税并入田赋结束了中国两千年的"人头税"——无地农民从此不再交税。第三、设立军机处——取代议政王大臣会议加强皇权提高决策效率。第四、改土归流——在西南少数民族地区废除世袭土司改派流官加强了中央集权。第五、秘密建储——将太子名字密封于匣藏于"正大光明"匾后避免皇子公开争夺。',
        evaluation:'雍正的历史评价极其两极分化。他在位仅十三年但完成的工作量超过了很多在位数十年的皇帝——是清朝制度建设的真正奠基人。没有雍正的财政整顿增收和机构改革就没有乾隆挥霍六十年的资本。但他对待政敌的手段残酷——即位过程充满疑点——也让他的形象蒙上了阴翳。"刻薄寡恩"与"改革明君"这两种评价至今仍在拉锯。',
        anecdotes:'"朕就是这样的汉子"——雍正奏折批语风格极度口语化生动鲜活。传位之谜——"传位十四子"改"传位于四子"的说法流传极广但学术上基本确定为后世编造的传说。每天睡四个小时——勤政到近乎自虐的程度据说是累死在皇帝岗位上的。暴毙之谜——雍正暴死圆明园死因众说纷纭有中风服丹被刺杀多种说法。'},
      {name:'乾隆',
        basicInfo:'爱新觉罗·弘历（1711—1799年），清朝第六位皇帝清高宗，雍正帝第四子。二十五岁即位于位六十年后退位为太上皇又训政三年实际执政六十三年是中国历史上实际执政时间最长的皇帝。在位期间清朝达到鼎盛——疆域超过一千三百万平方公里人口突破三亿。编纂《四库全书》——中国历史上规模最大的丛书。"十全武功"巩固了清朝的边疆统治。晚年宠信和珅吏治腐败，乾隆去世后仅四十五年鸦片战争爆发盛世与危机之间只隔了一道墙。',
        lifeStory:'乾隆是雍正精心培养的继承人——自幼受到最严格的帝王教育精通满汉蒙藏四种语言。1735年即位后他展现出惊人的精力——每天早朝后批阅奏折接见大臣处理事务直到深夜数十年如一日。他自诩"十全老人"——十次大规模军事行动（两平准噶尔一定回部两平大小金川平台湾降缅甸安南两降廓尔喀）奠定了清朝极盛时期的版图。1757年平定准噶尔从此天山南北纳入清朝版图——今天的新疆正是在乾隆时期完全归入中国。1796年为不超过祖父康熙的在位年限他禅位于十五子颙琰（嘉庆帝）。他以"十全武功""四库全书""六下江南"留名后世但也因文字狱和晚年宠信和珅埋下了衰落的种子。1799年去世享年八十九岁。',
        governance:'第一、巩固统一——平定准噶尔大小和卓之乱使新疆正式归入中国版图。第二、编纂《四库全书》——历时十五年动用四千余人抄写七部共七万九千余卷入编图书三千四百余种——保存了巨量古籍但禁毁的书籍也达三千余种。第三、六次南巡——巡视南方体察民情但也劳民伤财。第四、普免钱粮——五次普免全国赋税减轻农民负担。',
        evaluation:'乾隆将中国传统农业文明的国力推向了极致——人口疆域财富均达到了古代的最高峰。但他的盛世之下危机四伏：吏治腐败（和珅案发后抄出的家产折合银两达八亿两相当于清政府十五年的财政收入）、闭关锁国政策趋于极端、文字狱禁锢思想（据统计乾隆朝文字狱达一百三十余起）、八旗战斗力锐减。1793年英国使节马戛尔尼来华请求通商贸易——乾隆傲慢地回复"天朝物产丰盈无所不有原不藉外夷货物以通有无"。这一拒绝的决定错过了与世界工业文明对接的最后机会。',
        anecdotes:'"十全老人"——乾隆自诩有十大武功自称"十全老人"。"天朝物产丰盈"——拒绝马戛尔尼通商请求的名言被视为中国闭关锁国心态的典型表达。和珅跌倒嘉庆吃饱——和珅被抄家时家产相当于清政府十五年财政收入。六下江南——沿途开销巨大但留下的诗词和故事成为江南旅游文化的宝贵遗产。'},
      {name:'林则徐',
        basicInfo:'字元抚（1785—1850年），又字少穆，福建侯官（今福州）人，清代政治家、民族英雄。任湖广总督期间严禁鸦片卓有成效。1839年奉旨为钦差大臣赴广州查禁鸦片——在虎门海滩当众销毁鸦片二百三十七万余斤（约合1188吨）。鸦片战争爆发后被革职流放新疆伊犁——在流放途中写下"苟利国家生死以，岂因祸福避趋之"的千古名句。是中国近代"睁眼看世界的第一人"。',
        lifeStory:'林则徐以进士入仕历任多地地方官以清廉干练著称。任湖广总督时他率先在湖北严厉禁烟——收缴烟土烟具、配制戒烟药丸——成效显著。1838年他上书道光帝痛陈鸦片之害——"若犹泄泄视之是使数十年后中原几无可以御敌之兵且无可以充饷之银"。道光帝大受震动任命他为钦差大臣赴广州禁烟。1839年三月林则徐到达广州后——查封烟馆、传讯外商、严令交出鸦片。英国商务监督义律被迫令英商交出鸦片二万余箱。林则徐在虎门海滩挖池引入海水和石灰将鸦片全部销毁——历时二十三天围观的百姓和外商无不震慑。他还组织翻译西方报刊和书籍——编成《四洲志》——是中国第一次系统地了解世界。鸦片战争爆发后清廷将战败归咎于林则徐将其革职流放伊犁。在新疆他兴修水利勘查农田绘制边疆地图。1850年再次被起用为钦差大臣前往广西镇压太平天国起义途中病逝于潮州。',
        works:'虎门销烟——1839年在虎门海滩当众销毁鸦片二百三十七万余斤震惊世界。睁眼看世界——组织翻译《四洲志》《华事夷言》等西方著作和报刊——"师夷长技以制夷"的思想由他开启魏源发扬。《林文忠公政书》——收录其从政期间的奏疏和公牍。新疆水利——流放伊犁期间兴修坎儿井（人称"林公井"）和灌溉渠道。',
        evaluation:'林则徐是中国近代史上最受尊敬的民族英雄。他以一人之力对抗强大的鸦片利益集团和国际贩毒势力——"苟利国家生死以，岂因祸福避趋之"是他一生最好的写照。他超越时代之处在于——他不仅禁烟还主动了解西方——他认识到中国的落后不是因为武器不行而是对世界一无所知。虽然鸦片战争打败了，但他点燃的火种——"师夷长技"——成为了洋务运动和近代化改革的先声。',
        anecdotes:'"若犹泄泄视之"——上道光帝的奏折中痛陈鸦片危害的名句。"苟利国家生死以，岂因祸福避趋之"——流放伊犁途中所作是中国爱国主义精神的最经典表达。"林公井"——在新疆伊犁流放期间兴修水利当地人称为"林公井"至今仍有使用。'},
      {name:'曾国藩',
        basicInfo:'字伯涵（1811—1872年），号涤生，湖南湘乡（今双峰）人，晚清名臣。以在籍侍郎身份组建湘军（团练）平定太平天国运动。倡导洋务运动创办江南制造总局、安排中国第一批幼童赴美留学。与李鸿章左宗棠张之洞并称"晚清四大名臣"。其家书家训以"修身齐家治国平天下"为宗旨影响深远。被誉为中国传统文化中"立德立功立言三不朽"的典范。',
        lifeStory:'曾国藩二十八岁进士及第选为翰林院庶吉士在京期间师从理学大师唐鉴倭仁等人修身养性。1851年太平天国起义爆发势如破竹——1853年太平军攻占南京改名为天京。清廷的八旗和绿营兵屡战屡败。1853年曾国藩奉命在湖南办团练——他以儒生带乡农——在家乡以宗族血缘为纽带招募朴实农民以严格的儒家道德和纪律训练军队。湘军初期屡遭惨败——1854年靖港之败曾国藩羞愤投水自尽被部下救起。但他愈挫愈勇——"结硬寨打呆仗"——以稳扎稳打的战术逐步扭转战局。1864年湘军曾国荃部攻破天京太平天国运动被镇压。此后他主动裁撤湘军——"功成身退"——避免了功高震主的猜忌。晚年倡导洋务运动兴办江南制造总局、设翻译馆翻译西方科技书籍、推动派遣中国第一批幼童留学美国。',
        works:'平定太平天国——以湘军十余年血战最终攻克天京结束了这场死亡数千万人的浩劫。洋务运动——创办江南制造总局（中国第一家近代化军事工厂）、福州船政局等。培养人才——幕府中聚集了李鸿章左宗棠彭玉麟等大批后来成为晚清栋梁的人物。家书——《曾国藩家书》千余封以"勤俭谦"教诫子弟是中国家训文化的巅峰。',
        evaluation:'曾国藩被许多人视为中国传统文化中最后一个"完人"——"立德立功立言"三不朽。他以一介书生创建湘军挽救了清王朝的覆亡——是"修齐治平"理想人格在近代的最后一次完整实现。但他在处理天津教案（1870年）时屈从外国压力不敢抗争——成为其一生的污点。历史给他的定位是"传统中国最后一位完人也是近代中国最早的改革者"——他站在新旧两个时代的交界处。',
        anecdotes:'"结硬寨打呆仗"——曾国藩的军事哲学不打无准备之仗每攻一城先挖壕筑墙确保自身立于不败。"屡败屡战"——靖港兵败后上奏把"屡战屡败"改为"屡败屡战"一字之差精神完全不同。主动裁撤湘军——攻克天京后"功成身退"避免了兔死狗烹的命运。天津教案——处理天津教案时被国人骂为"卖国贼"他自己也引为毕生之憾。'},
      {name:'李鸿章',
        basicInfo:'字渐甫（1823—1901年），号少荃，安徽合肥人，晚清重臣。早年师从曾国藩入幕府受其赏识。后独立组建淮军（从安庆率团练乘英国轮船抵上海）。与曾国藩联手镇压太平天国和捻军。此后倡导洋务运动三十余年——创办轮船招商局、开平矿务局、天津电报局、中国第一条铁路（唐胥铁路）等近代企业；筹建北洋水师——亚洲最强的近代化舰队。先后代表清政府签订《马关条约》《辛丑条约》等一系列不平等条约。临终前留下"三百年来伤国步八千里外吊民残"的哀叹。',
        lifeStory:'李鸿章二十四岁中进士选庶吉士。太平天国运动时期回安徽办团练后入曾国藩幕府。1862年奉命组建淮军率九千人马从安庆乘英国轮船沿长江抵上海——"以夷制夷"——用洋枪洋炮装备部队实力迅速壮大。在镇压太平天国和捻军中淮军成为清军主力。1870年起他事实上成为晚清外交和洋务的总负责人——一手创建了亚洲最强大的北洋水师（拥有铁甲舰定远镇远等各型军舰七十余艘）。但1894年甲午战争中北洋水师全军覆没他一手建立的功业毁于一旦。1895年作为全权代表赴日本马关谈判——被日本浪人刺杀面部中枪但仍坚持谈判——最终签下丧权辱国的《马关条约》。1901年八国联军侵华后再签《辛丑条约》——赔款四亿五千万两白银（按当时中国人口每人一两）——同年病逝。',
        evaluation:'李鸿章是中国近代史上最矛盾的悲剧人物。他是一个极其能干的人——眼光超前创办了中国第一批近代化企业建造了亚洲最大的舰队——但同时也是最屈辱的条约签订者。梁启超评价他"吾敬李鸿章之才，吾惜李鸿章之识，吾悲李鸿章之遇"——李的悲剧在于他以一人之力无法改变整个体制的腐朽。日本首相伊藤博文评价他说："大清国唯一有能耐和世界列强一争长短之人"——这句评价道出了李的价值也道出了他背后空无一人的悲哀。',
        anecdotes:'挨枪子谈判——在马关被日本浪人开枪击中面部子弹留在颧骨下他坚持不取弹继续谈判以博取国际同情。临终诗——"劳劳车马未离鞍临事方知一死难。三百年来伤国步八千里外吊民残。秋风宝剑孤臣泪落日旌旗大将坛。海外尘氛犹未息请君莫作等闲看。"北洋水师覆灭——听说北洋水师在威海卫全军覆没时李鸿章说"我一手经营三十年的北洋水师完了"。'},
      {name:'左宗棠',
        basicInfo:'字季高（1812—1885年），号湘上农人，湖南湘阴人，晚清名臣。早年科举不顺——三试不第——却自学经世致用之学精通地理军事和农业。太平天国时期入湘军幕府为曾国藩出谋划策后独立领军。最主要的功绩是——年届六十九岁抬棺出征率领湘军收复被阿古柏侵占十二年的新疆全境（除伊犁外），并迫使沙俄通过谈判归还伊犁。如果没有左宗棠的收复行动，今天中国版图上可能就没有占国土面积六分之一的新疆。',
        lifeStory:'左宗棠少时家贫但志向远大——自比诸葛亮自号"今亮"。他三次参加会试均不第——这在当时意味着仕途断绝——但他没有消沉而是潜心研究地理军事农学等"经世致用"之学。四十多岁仍是一介布衣，直到太平天国起义爆发曾国藩慧眼识珠邀请他入幕。1860年起他独立率军征战——从太平军手中收复浙江全境。1866年创办福州船政局——中国第一家近代造船厂。最辉煌的功绩是收复新疆：1865年阿古柏在英俄支持下侵占新疆建立伪政权；清廷内部发生"海防"与"塞防"之争——李鸿章主张放弃新疆集中力量发展海军，左宗棠力排众议主张"海防塞防并重"。1875年清廷任命他督办新疆军务——他已六十四岁却毅然抬棺出征。他以"先北后南缓进急战"方略仅用一年多时间便收复新疆全境。此后又通过外交谈判迫使沙俄归还伊犁。',
        works:'收复新疆——"先北后南缓进急战"仅一年余收复新疆全境是中国近代史上最伟大的军事收复行动。创办福州船政局——中国第一家近代造船厂。洋务思想——"师夷长技以制夷"在福建浙江等地兴办近代企业。在新疆兴修水利推广农业——"左公柳"（他命士兵在沿途种植的柳树）至今仍存。',
        evaluation:'左宗棠是中国近代史上最伟大的民族英雄之一。他以六十九岁高龄抬棺出征——"不收复新疆誓不生还"——这种为国捐躯的决心感天动地。新疆占中国领土六分之一，如果没有左宗棠——今天的中国西部边界很可能就停在嘉峪关。晚清四大名臣中左宗棠是唯一不签不平等条约的人——他用自己的行动证明面对列强中国人的骨头可以很硬。',
        anecdotes:'抬棺出征——六十九岁高龄抬着棺材西征以示"不收复新疆誓不生还"。左公柳——西征路上命士兵沿途种植柳树改善生态环境。"天下不可一日无湖南湖南不可一日无左宗棠"——时人对他的评价。自比诸葛亮——自号"今亮"书房楹联"身无半亩心忧天下读破万卷神交古人"。'},
      {name:'慈禧太后',
        basicInfo:'（1835—1908年），叶赫那拉氏，满洲镶蓝旗人，清朝咸丰帝懿贵妃，同治光绪两朝的实际最高统治者。统治中国四十七年（1861—1908年）——是武则天之后中国最有权力的女性。发动辛酉政变夺取最高权力，垂帘听政掌权近半个世纪。镇压戊戌变法囚禁光绪帝于中南海瀛台。在位期间中国经历了洋务运动（同情但未能深入推动）、甲午战争、戊戌变法、义和团运动和八国联军侵华——一次次丧权辱国割地赔款。她的统治深刻影响了中国近代史的走向，是中国近代最具争议的人物之一。',
        lifeStory:'慈禧十七岁被选入宫为咸丰帝懿贵人——因生同治帝（咸丰唯一的儿子）母以子贵升为懿贵妃。1861年咸丰帝在热河驾崩——同治帝年仅六岁。慈禧联合恭亲王奕訢发动"辛酉政变"一举铲除了肃顺等顾命八大臣——开始长达四十七年的垂帘听政。她支持洋务运动——圆明园被焚后修建颐和园——扩建海军——但对变革的理解始终停留在"引进技术"层面。1898年维新变法触及制度变革时她毫不留情地发动政变镇压——囚光绪帝于瀛台杀六君子。1900年利用义和团攻打外国使馆——八国联军攻入北京她携光绪帝逃往西安——《辛丑条约》后中国彻底沦为半殖民地。1908年病逝于北京——死前一日光绪帝暴亡（毒杀说证据日益充分）。',
        evaluation:'慈禧太后是中国近代史上最具争议的人物。支持她的人认为：她在风雨飘摇中维持了清政府的运转——换一个人来未必做得更好。反对她的人认为：她将个人权力置于国家命运之上——以血腥手段扼杀了每一次变革的机会——使得中国错过了近代化的关键时间窗口。有一点可以确定：她在位四十七年中国挨的每一次打割的每一次地都发生在她眼皮底下——无论她个人多么精明强干这些历史灾难的责任都无法回避。',
        anecdotes:'辛酉政变——联合恭亲王一举铲除肃顺等顾命八大臣——用慈禧的话说"肃顺辈无人君之礼"。挪用海军经费修颐和园——挪用了北洋水师的购舰经费修建颐和园导致北洋水师在甲午海战中未能购买新型军舰。光绪之死——2008年光绪头发检测发现大量砷元素——被毒杀的可能性极大。临死前的安排——临终仍指定三岁的溥仪为帝企图继续保持权力。'},
      {name:'孙中山',
        basicInfo:'名文字德明号逸仙（1866—1925年），广东香山（今中山）人，中国近代民族民主主义革命的先行者。创建兴中会（1894年）、同盟会（1905年），提出"驱除鞑虏恢复中华创立民国平均地权"的革命纲领和"三民主义"（民族民权民生）。领导辛亥革命推翻延续两千余年的封建帝制。1912年就任中华民国临时大总统，被尊为"国父"。晚年改组国民党实行"联俄联共扶助农工"三大政策。留有遗言"革命尚未成功同志仍须努力"。',
        lifeStory:'孙中山出身农民家庭年少时随兄赴檀香山（夏威夷）求学第一次接触到西方现代文明。后学医于香港西医书院——以优异成绩毕业。但他很快认识到"医术救人不如医术救国"——1894年上书李鸿章提出改革建议石沉大海。同年他在檀香山成立兴中会开始革命活动。此后数十年间——他组织了十次武装起义全部失败（最惨烈的是1911年的黄花岗起义七十二烈士殉难）。他在海外流亡十六年——日本欧美东南亚——四处演讲募款联络同志。1911年10月10日武昌起义爆发——当时孙中山正在美国丹佛奔走。辛亥革命成功各省纷纷响应——1912年1月1日孙中山在南京就任中华民国临时大总统。但仅三个月后便将总统之位让给袁世凯。此后他继续为民主共和奋斗——"二次革命""护法运动""北伐"。晚年改组国民党——"联俄联共扶助农工"——1925年在北京病逝。',
        works:'三民主义——民族主义（推翻满清争取民族独立）、民权主义（建立民主共和国人民享有选举罢免创制复决四权）、民生主义（平均地权节制资本）。辛亥革命——推翻了两千余年的帝制建立了亚洲第一个民主共和国。建国方略——构想了中国现代化建设的蓝图包括修建十万英里铁路三大港口等宏伟计划。',
        evaluation:'孙中山的伟大在于——他以一人之力在黑暗中点燃了推翻帝制建立共和的星星之火。虽然他生前屡战屡败始终未能亲眼看到革命成功后的中国——但"天下为公"的理念和民主共和的理想使千百万人追随他的事业。"国父"的称号实至名归——他是现代中国第一个从"臣民"变为"公民"的精神之父。他的局限性也很明显——在强大的北洋军阀势力和外国干涉面前，没有武力支撑的革命理想终究是脆弱的。',
        anecdotes:'"革命尚未成功"——临终遗言"余致力国民革命凡四十年其目的在求中国之自由平等。积四十年之经验深知欲达到此目的必须唤起民众及联合世界上以平等待我之民族共同奋斗。革命尚未成功同志仍须努力。"上书李鸿章——1894年上书李鸿章提出改革建议没有回音从此转向革命。伦敦蒙难——1896年在伦敦被清朝使馆诱捕秘密囚禁经英国友人营救脱险后成为国际知名人物。'},
      {name:'康有为',
        basicInfo:'字广厦号长素（1858—1927年），广东南海（今佛山）人，晚清维新派领袖。1895年联合在京赶考的一千三百余名举人"公车上书"反对签订《马关条约》。1898年在光绪帝支持下主导"戊戌变法"（百日维新）。变法失败后流亡海外十六年游历三十余国。著有《大同书》构想消除国界阶级种族性别差异的理想社会，《新学伪经考》《孔子改制考》为变法提供理论基础。是中国近代重要的思想家和改革家。',
        lifeStory:'康有为早年研究儒家经典后到香港上海接触到西方文明——"始知西人治国有法度不得以古旧之夷狄视之"。他创造性地"托古改制"——将孔子解释为"改制之王"论证变法维新的正当性。1895年甲午战败《马关条约》签订消息传来——正在北京参加会试的康有为联合千余名举人"公车上书"要求拒和迁都变法——这是中国近代第一次大规模的知识分子政治请愿活动。1898年光绪帝决心变法——任命康有为总理衙门章京上行走——开始百日维新。但仅一百零三天后慈禧发动政变——康有为在英国保护下流亡海外。此后十六年他游历三十余国——观察各国政治制度——继续鼓吹君主立宪。1911年辛亥革命推翻帝制后他仍坚持保皇——成为时代的"遗老"。1917年参与张勋复辟闹剧彻底失去公信力。晚年隐居青岛1927年病逝。',
        works:'"公车上书"——1895年联合千余名举人上书是中国近代第一次大规模知识分子请愿。戊戌变法——推动光绪帝在政治经济文教军事等领域颁布了数十道改革上谕。《大同书》——构想了一个"无邦国无帝王无阶级无种族无性别无家庭"的乌托邦社会。《孔子改制考》——用考据学的方法论证孔子是"托古改制"的改革者为变法提供儒学依据。',
        evaluation:'康有为是晚清思想界最有影响力的人物之一。他最早系统地将西方政治制度介绍到中国并借助儒学的话语体系为变革提供合法性。但他性格中的傲慢、固执和脱离实际也很突出——他坚信君主立宪是唯一的救国之道路但当辛亥革命推翻帝制后他仍不肯与时俱进终于沦为时代的落伍者。《大同书》虽然在他在世时没有出版但其乌托邦理想至今闪烁着超越时代的光芒。',
        anecdotes:'公车上书——率千名举人在北京集体请愿是中国近代第一次大规模的学生运动。自称"长素"——意思是"超越素王"（孔子被尊为"素王"）可见其自负程度。流亡十六年——足迹遍布三十余国从日本到加拿大从印度到墨西哥。晚年保皇——辛亥革命后仍坚持保皇甚至参与张勋复辟被时人笑为"康圣人"。'},
    ],
    inventions:['《四库全书》','《红楼梦》','京剧','圆明园','《康熙字典》'],"""

